const SF_EVIDENCE = {"modpack:engineering_assembly":"modpack:craft_engineering_assembly","ic2cre:generator":"modpack:craft_ic2_generator","modpack:information_interface":"modpack:craft_information_interface","modpack:heavy_industry_control":"modpack:craft_heavy_industry_control","modpack:reactor_control":"modpack:craft_reactor_control","modpack:space_control_core":"modpack:craft_space_control_core","modpack:quantum_control":"modpack:craft_quantum_control"};
ItemEvents.crafted((e) => {
  const key = SF_EVIDENCE[String(e.item.id)];
  if (!key) return;
  const p = e.player || e.entity;
  try { ProgressiveStages.addCounter(p, key, 1); } catch (err) {
    console.log('[starforge] counter bump failed: ' + err);
  }
});

